                let rules = rt::watch::Rules {
                    thing: "document",
                    gone_when: Some(("documentId", this.document_id.clone())),
                    job,
                    until,
                    codes: crate::error::ERROR_CODES,
                    observe: progress.map(|f| crate::operations::Processing::observer(f, "document", this.document_id.clone())),
                };
                rt::watch::follow(move |o| watch.options(o).send(), rules, wopts, Error::is_not_found).await?;
