impl rt::Follow for FolderScope {
    type Output = crate::types::Folder;
    type Error = Error;
    type Progress = crate::operations::Processing;

    fn follow(&self, job: Option<String>) -> rt::Waiting<Self::Output, Error, crate::operations::Processing> {
        self.follow_job(job)
    }
}

