/// A scope, `caitlyn.core.operations(knowledgeBaseId, operationId)`: one thing, with every call about
/// it. Making it sends nothing.
#[derive(Clone, Debug)]
pub struct OperationScope {
    #[allow(dead_code)]
    pub(crate) core: rt::Client,
    pub(crate) knowledge_base_id: String,
    pub(crate) operation_id: String,
}

impl OperationScope {
    pub(crate) fn from_ids(core: rt::Client, ids: Vec<String>) -> Self {
        let mut ids = ids.into_iter();
        OperationScope {
            core,
            knowledge_base_id: ids.next().unwrap_or_default(),
            operation_id: ids.next().unwrap_or_default(),
        }
    }

    /// The `knowledgeBaseId` this scope holds.
    pub fn knowledge_base_id(&self) -> &str {
        &self.knowledge_base_id
    }

    /// The `operationId` this scope holds.
    pub fn operation_id(&self) -> &str {
        &self.operation_id
    }

    /// The identifier of the thing this scope is.
    pub fn id(&self) -> &str {
        &self.operation_id
    }

    /// Gets one Operation: where its work is, how far it has got, and how it ended.
    ///
    /// The caller needs the access it would need to read the Operation's target; anyone else gets 404.
    /// Everyday code waits through the scope the work is on (`doc.wait()`, `kb.wait()`) instead.
    ///
    /// Errors: [`Error::Internal`] (500), [`Error::PermissionDenied`] (403), [`Error::ServiceUnavailable`]
    /// (503), [`Error::TooManyRequests`] (429), [`Error::Unauthenticated`] (401), [`Error::Validation`]
    /// (400), [`Error::NotFound`] (404); another status the API models has its own variant too
    /// ([`Error::NotFound`] for 404), and any other status is [`Error::Api`].
    ///
    /// Since Caitlyn 5.144.0; beta.
    pub fn get(&self) -> GetOperationRequest {
        let mut input = GetOperationInput::default();
        input.knowledge_base_id = self.knowledge_base_id.clone();
        input.operation_id = self.operation_id.clone();
        GetOperationRequest::new(
            self.core.clone(),
            input,
            vec![self.knowledge_base_id.clone(), self.operation_id.clone()],
        )
    }

    /// Cancels an Operation's work.
    ///
    /// Work not started yet is dropped; work running is stopped. Only `document_ingestion` can be
    /// cancelled today: a cancelled first version removes the document, and a cancelled new version
    /// leaves the current one serving. Any other kind is refused with 409 `OPERATION_NOT_CANCELLABLE`,
    /// and a final Operation with 409 `CONFLICT`. Returns the Operation, which becomes `cancelled` once
    /// the work has stopped.
    ///
    /// Needs the files update permission. For `document_ingestion` the server also checks, on the
    /// document the Operation reads, the permission that started it (`files.create` for a new document,
    /// `files.update` for a new version or a retry) and the document's readers. A caller without it
    /// gets 404, as for an Operation it may not see.
    ///
    /// Errors: [`Error::Internal`] (500), [`Error::PermissionDenied`] (403), [`Error::ServiceUnavailable`]
    /// (503), [`Error::TooManyRequests`] (429), [`Error::Unauthenticated`] (401), [`Error::Validation`]
    /// (400), [`Error::Conflict`] (409), [`Error::NotFound`] (404); another status the API models has its
    /// own variant too ([`Error::NotFound`] for 404), and any other status is [`Error::Api`].
    ///
    /// Since Caitlyn 5.144.0; beta.
    pub fn cancel(&self) -> CancelOperationRequest {
        let mut input = CancelOperationInput::default();
        input.knowledge_base_id = self.knowledge_base_id.clone();
        input.operation_id = self.operation_id.clone();
        CancelOperationRequest::new(
            self.core.clone(),
            input,
            vec![self.knowledge_base_id.clone(), self.operation_id.clone()],
        )
    }

    /// Watches an Operation: the whole Operation each time it changes, ending when it is final.
    ///
    /// The stream sends `operation.updated` on each change and ends with `operation.finished`. With
    /// `Last-Event-ID`, a dropped connection resumes without losing a change.
    ///
    /// Errors: [`Error::Internal`] (500), [`Error::PermissionDenied`] (403), [`Error::ServiceUnavailable`]
    /// (503), [`Error::TooManyRequests`] (429), [`Error::Unauthenticated`] (401), [`Error::Validation`]
    /// (400), [`Error::NotFound`] (404); another status the API models has its own variant too
    /// ([`Error::NotFound`] for 404), and any other status is [`Error::Api`].
    ///
    /// Since Caitlyn 5.144.0; beta.
    pub fn watch(&self) -> WatchOperationRequest {
        let mut input = WatchOperationInput::default();
        input.knowledge_base_id = self.knowledge_base_id.clone();
        input.operation_id = self.operation_id.clone();
        WatchOperationRequest::new(
            self.core.clone(),
            input,
            vec![self.knowledge_base_id.clone(), self.operation_id.clone()],
        )
    }
}

/// The collection `caitlyn.core.uploads`: its list, create and other calls on all of them.
#[derive(Clone, Debug)]
pub struct CoreUploads {
    #[allow(dead_code)]
    pub(crate) core: rt::Client,
}

impl CoreUploads {
    pub(crate) fn from_ids(core: rt::Client, ids: Vec<String>) -> Self {
        let _ = ids;
        CoreUploads { core }
    }

    /// Reserves a short-lived slot for a file's bytes and returns a presigned URL bound to their
    /// checksum.
    ///
    /// Send the bytes with `uploadMethod` to `uploadUrl`, with every header in `requiredHeaders`,
    /// before `expiresAt`; then pass the upload's `id` to the operation that uses it. Files can be at
    /// most 2 GB. For an attachment, name the conversation in `purpose`: the conversation's attachment
    /// settings are checked here, before the bytes travel. The SDKs' `core.uploads.send(file)` does all of
    /// this, and their document and attachment helpers call it for you. Many files at once go through an
    /// ingestion batch instead, which signs one upload policy for them all.
    ///
    /// Errors: [`Error::Internal`] (500), [`Error::PermissionDenied`] (403), [`Error::ServiceUnavailable`]
    /// (503), [`Error::TooManyRequests`] (429), [`Error::Unauthenticated`] (401), [`Error::Validation`]
    /// (400), [`Error::Conflict`] (409), [`Error::PayloadTooLarge`] (413), [`Error::UnprocessableContent`]
    /// (422); another status the API models has its own variant too ([`Error::NotFound`] for 404), and any
    /// other status is [`Error::Api`].
    ///
    /// Since Caitlyn 5.144.0; beta.
    pub fn reserve(
        &self,
        file_name: impl Into<String>,
        content_type: impl Into<String>,
        byte_size: i64,
        sha256: impl Into<String>,
    ) -> CreateUploadRequest {
        let mut input = CreateUploadInput::default();
        input.file_name = file_name.into();
        input.content_type = content_type.into();
        input.byte_size = byte_size;
        input.sha256 = sha256.into();
        CreateUploadRequest::new(self.core.clone(), input, vec![])
    }
}

