/// Uploads a file: hashes it, reserves the upload with CreateUpload (with `purpose`), then sends the bytes to the
/// upload URL with exactly the required headers (PROTOCOL.md 14).
pub(crate) async fn send_upload(
    core: &rt::Client,
    file: rt::UploadFile,
    purpose: Option<UploadPurpose>,
    opts: rt::CallOptions,
) -> Result<CreateUploadResult, Error> {
    let prepared = core.prepare_file(&file, &opts).await.map_err(Error::from)?;
    let input = CreateUploadInput {
        file_name: prepared.name().to_owned(),
        content_type: prepared.content_type().to_owned(),
        byte_size: prepared.size() as i64,
        sha256: prepared.sha256().to_owned(),
        purpose,
        ..Default::default()
    };
    let up = CreateUploadRequest::new(core.clone(), input, vec![])
        .options(opts.clone())
        .send()
        .await?;
    core.put_presigned(&up.upload_method, &up.upload_url, &up.required_headers, &prepared, &opts)
        .await
        .map_err(Error::from)?;
    Ok(up)
}

impl CoreUploads {
    /// Uploads a file (PROTOCOL.md 14): it hashes the file with streaming reads (spooling a one-shot
    /// reader, to a temporary file past 8 MiB), reserves the upload, then sends the bytes to the upload URL
    /// with exactly the required headers (no Caitlyn credentials go there), retried as a retry-safe call. A
    /// file over 2 GB fails with the code `FILE_TOO_LARGE` and a path that changed after it was hashed with
    /// `FILE_CHANGED`, before anything more is sent; bytes the upload URL does not take give
    /// `UPLOAD_PUT_FAILED`. It returns the upload: pass its `id` to the call that uses it.
    pub fn send(&self, file: impl Into<rt::UploadFile>) -> rt::Call<CreateUploadResult, Error> {
        let core = self.core.clone();
        let file = file.into();
        rt::Call::new(move |opts| Box::pin(async move { send_upload(&core, file, None, opts).await }))
    }

    /// As [`send`](Self::send), reserving the upload with `purpose`, for an upload whose use decides
    /// whether it is accepted (an agent's avatar picture, a conversation's attachment).
    pub fn send_for(&self, file: impl Into<rt::UploadFile>, purpose: UploadPurpose) -> rt::Call<CreateUploadResult, Error> {
        let core = self.core.clone();
        let file = file.into();
        rt::Call::new(move |opts| Box::pin(async move { send_upload(&core, file, Some(purpose), opts).await }))
    }
}

/// What `kb.ingestion().sync(…)` keeps in step, and how: a directory (`"./policies"`, or `SyncInput::dir`) or
/// `SyncInput::items(…)`, then its options (`folder`, `policy`, `external_id`, `remove_missing`, `confirm`, `resolver`,
/// `on_progress`, `on_item`, …).
pub type SyncInput = rt::sync::SyncInput<
    crate::types::IngestionPolicy,
    crate::types::IngestionBatch,
    crate::types::IngestionBatchItem,
    crate::types::IngestionItemResolution,
    crate::types::EstimateIngestionResult,
>;

/// What `kb.ingestion().sync(…)` returns: the finished batch and every item.
pub type SyncReport = rt::sync::SyncReport<crate::types::IngestionBatch, crate::types::IngestionBatchItem>;

/// What `kb.ingestion().estimate_sync(…)` returns, and `confirm` is given: the planned batch, its items and its estimate.
pub type SyncPlan =
    rt::sync::SyncPlan<crate::types::IngestionBatch, crate::types::IngestionBatchItem, crate::types::EstimateIngestionResult>;

/// One progress report of `kb.ingestion().sync(…)`.
pub type IngestionProgress = rt::sync::IngestionProgress<crate::types::IngestionBatchItem>;

pub use rt::sync::{LocalFile, SyncItem, SyncPhase};

impl KnowledgeBaseIngestion {
    /// Keeps the knowledge base in step with a folder of files, or a list of items, through one ingestion
    /// batch (PROTOCOL.md 15). Files are keyed by their relative path and go to `/` unless `folder` says
    /// otherwise. It hashes each file, creates the batch (`start: manual`, 10,000 items a call), waits
    /// until it is planned and prices it, asks `confirm` and the `resolver` when they are set (an item the
    /// policy left unresolved with no resolver fails with `INGESTION_BATCH_UNRESOLVED`, leaving the batch
    /// planned), starts it, sends each file awaiting upload under the batch's upload policy (6 at once by
    /// default), reports the uploads 100 at a time, waits until the batch has ended and returns every item.
    /// A file whose upload fails is reported with `UPLOAD_FAILED` and the rest carry on. Cancelling
    /// (`cancel_on`) stops new uploads, aborts those in flight and fails with [`Error::Cancelled`]; with
    /// `cancel_ingestion(true)` it also cancels the batch.
    pub fn sync(&self, input: impl Into<SyncInput>) -> rt::Call<SyncReport, Error> {
        let core = self.core.clone();
        let kb = self.knowledge_base_id.clone();
        let input = input.into();
        rt::Call::new(move |opts| Box::pin(async move { rt::sync::run(core, kb, input, crate::error::ERROR_CODES, opts).await }))
    }

    /// What `sync` would do and cost, before anything is uploaded: it hashes the files, creates the batch,
    /// waits until it is planned and prices the items that need bytes (PROTOCOL.md 15, steps 1 to 3). The
    /// batch is left planned.
    pub fn estimate_sync(&self, input: impl Into<SyncInput>) -> rt::Call<SyncPlan, Error> {
        let core = self.core.clone();
        let kb = self.knowledge_base_id.clone();
        let input = input.into();
        rt::Call::new(move |opts| Box::pin(async move { rt::sync::estimate(core, kb, input, crate::error::ERROR_CODES, opts).await }))
    }
}

/// The files `batch.upload(files)` and `batch.estimate_upload().files(…)` take: by item path
/// (`BatchFiles::by_path([("/hr/leave.pdf", file)])`, or a `HashMap`, a `BTreeMap`, an array or a `Vec` of pairs), or
/// `BatchFiles::with(|item| …)`, a file for each item as it is needed.
pub type BatchFiles = rt::sync::BatchFiles<crate::types::IngestionBatchItem>;

/// What `batch.upload(files)` gives: `batch`, the items it dealt with, `not_given` and `unmatched`.
pub type BatchUpload = rt::sync::BatchUpload<crate::types::IngestionBatch, crate::types::IngestionBatchItem>;

/// `batch.upload(files)`, with its options; await it for the handle, or `.wait()` for the finished batch.
pub type BatchUploadRequest = rt::batch::UploadRequest<
    crate::types::IngestionBatch,
    crate::types::IngestionBatchItem,
    crate::types::IngestionBatch,
    crate::operations::KnowledgeBaseEventStream,
    Error,
    crate::operations::Processing,
>;

/// `batch.estimate_upload()`, with its optional files; await it for the estimate.
pub type EstimateUploadRequest =
    rt::batch::EstimateUploadRequest<crate::types::IngestionBatchItem, crate::types::EstimateIngestionResult, Error>;

impl BatchScope {
    /// Sends the batch's files (PROTOCOL.md 15) with the steps `ingestion().sync(…)` uses: the items
    /// awaiting upload that `files` has a file for, 6 at a time, under an upload policy renewed as it runs
    /// low, reported to CompleteIngestionBatchUploads 100 at a time. Files are not hashed: the form carries
    /// each item's checksum, and a file whose size is not the item's fails it with `FILE_CHANGED` before
    /// anything is sent. An upload that still fails fails its item only (`UPLOAD_FAILED`). An awaiting item
    /// with no file is left awaiting (`not_given`), and a given path no awaiting item has is `unmatched`.
    /// The batch must have started: a draft, or a planned batch waiting for `start()`, fails with
    /// `INGESTION_BATCH_NOT_STARTED` (status 0) with nothing sent; a `when_planned` batch still planning is
    /// followed until it runs. Cancelling aborts the uploads and leaves the batch as it is. Await it for
    /// the handle (`result()` is the [`BatchUpload`]), or `.wait()` for the [`IngestionBatch`] once it has
    /// ended.
    pub fn upload(&self, files: impl Into<BatchFiles>) -> BatchUploadRequest {
        let (waiter, watcher) = (self.clone(), self.clone());
        rt::batch::UploadRequest::new(
            self.core.clone(),
            self.knowledge_base_id.clone(),
            self.ingestion_batch_id.clone(),
            files.into(),
            crate::error::ERROR_CODES,
            move || waiter.wait(),
            move || watcher.watch().send(),
        )
    }

    /// What uploading the batch's files would take and cost, before it is started (PROTOCOL.md 15): one
    /// EstimateIngestion (10,000 documents a call, added together) for the items that need bytes (`add`,
    /// `new_version`, `overwrite`), each described by name, content type and size: from its file with
    /// `.files(…)`, with the hints the file carries, or from the item. Nothing is hashed or read beyond a
    /// file's size. A draft batch fails with `INGESTION_BATCH_NOT_PLANNED` (status 0) with nothing sent; a
    /// planning one is waited on until planned. With nothing to price, the estimate is empty and no call is
    /// sent.
    pub fn estimate_upload(&self) -> EstimateUploadRequest {
        rt::batch::EstimateUploadRequest::new(
            self.core.clone(),
            self.knowledge_base_id.clone(),
            self.ingestion_batch_id.clone(),
            crate::error::ERROR_CODES,
        )
    }
}
